def area(width, height):
    """Return the area of a width by height rectangle."""
    return width * height

def min_max(nums):
    """Return the smallest and largest number as a tuple."""
    return min(nums), max(nums)

def grade(score):
    if score < 0 or score > 100:
        return "invalid"       # guard clause: odd cases first
    if score >= 90:
        return "A"
    return "not A"

print(area(3, 4))              # 12
low, high = min_max([4, 9, 1])
print(low, high)               # 1 9
print(grade(95), grade(120))   # A invalid

def factorial(n):
    if n <= 1:                   # base case
        return 1
    return n * factorial(n - 1)  # recursive case: a smaller problem

print(factorial(5))              # 120

def total(nums):
    if not nums:                 # empty list: nothing to add
        return 0
    return nums[0] + total(nums[1:])

print(total([4, 5, 6]))          # 15

def count_items(data):
    """Count the non-list items in a nested list."""
    count = 0
    for item in data:
        if isinstance(item, list):
            count += count_items(item)   # recurse into the sublist
        else:
            count += 1
    return count

print(count_items([1, [2, 3], [[4], 5]]))   # 5

